def factorial(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1  # base case
    return n * factorial(n - 1)  # recursive case

print(factorial(5))  # 120

def recursive_binary_search(values, target, low, high):
    if low > high:
        return -1

    mid = (low + high) // 2
    if values[mid] == target:
        return mid
    if target < values[mid]:
        return recursive_binary_search(values, target, low, mid - 1)
    return recursive_binary_search(values, target, mid + 1, high)

values = [3, 7, 12, 18, 25]
print(recursive_binary_search(values, 18, 0, len(values) - 1))

def inorder(node):
    if node is None:
        return
    inorder(node.left)
    print(node.key)
    inorder(node.right)

def iterative_factorial(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for value in range(2, n + 1):
        result *= value
    return result
